#!/usr/bin/python
import os
import sqlite3
import sys

LOCK_TIMEOUT_SECONDS = 5.0


def usage():
    sys.stderr.write('usage: reserve.py REQUEST_ID POSITIVE_QUANTITY\n')
    return 2


def main():
    if len(sys.argv) != 3 or not sys.argv[1]:
        return usage()

    request_id = sys.argv[1]
    try:
        quantity = int(sys.argv[2])
    except ValueError:
        return usage()
    if quantity <= 0:
        return usage()

    base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    path = os.path.join(base, 'stock.db')
    db = sqlite3.connect(path, timeout=LOCK_TIMEOUT_SECONDS)
    try:
        # Take the write reservation before reading either table.  SQLite then
        # serializes the complete check/decrement/record operation.
        db.execute('BEGIN IMMEDIATE')

        old = db.execute(
            'SELECT quantity FROM reservations WHERE request_id=?',
            (request_id,)).fetchone()
        if old is not None:
            db.commit()
            print 'reserved %s %d' % (request_id, old[0])
            return 0

        changed = db.execute(
            'UPDATE stock SET remaining=remaining-? '
            'WHERE id=1 AND remaining>=?',
            (quantity, quantity))
        if changed.rowcount != 1:
            db.rollback()
            sys.stderr.write('insufficient stock\n')
            return 1

        db.execute(
            'INSERT INTO reservations (request_id, quantity) VALUES (?, ?)',
            (request_id, quantity))
        db.commit()
        print 'reserved %s %d' % (request_id, quantity)
        return 0
    except sqlite3.OperationalError, error:
        try:
            db.rollback()
        except sqlite3.Error:
            pass
        sys.stderr.write('reservation failed: %s\n' % error)
        return 3
    except sqlite3.Error, error:
        try:
            db.rollback()
        except sqlite3.Error:
            pass
        sys.stderr.write('reservation failed: %s\n' % error)
        return 4
    finally:
        db.close()


if __name__ == '__main__':
    sys.exit(main())

